{{!-- Styling parameters: class, titleClass, gridClass --}}
{{#with this as |ghostcnStyles|}}
{{#get "authors" limit="100" include="count.posts"}}
{{#if authors}}<section class="ghcn-author-list{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" aria-label="Authors">
  {{#if ghostcnStyles.heading}}<h2 class="ghcn-author-list__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{ghostcnStyles.heading}}</h2>{{/if}}
  <div class="ghcn-author-list__grid{{#if ghostcnStyles.gridClass}} {{ghostcnStyles.gridClass}}{{/if}}">{{#foreach authors}}
    {{> "components/author-card" class=ghostcnStyles.cardClass titleClass=ghostcnStyles.cardTitleClass avatarClass=ghostcnStyles.avatarClass descriptionClass=ghostcnStyles.descriptionClass}}
  {{/foreach}}</div>
</section>{{else}}{{#if ghostcnStyles.emptyText}}<section class="ghcn-author-list{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}"><p class="ghcn-author-list__empty">{{ghostcnStyles.emptyText}}</p></section>{{/if}}{{/if}}
{{/get}}
{{/with}}

.ghcn-author-list { box-sizing: border-box; min-width: 0; margin-block: var(--ghcn-section-space, clamp(24px, 4vw, 48px)); font-family: inherit; font-size: var(--ghcn-text-body, 16px); line-height: 1.5; color: var(--foreground); width: min(100% - 32px, 1152px); margin-inline: auto; }
.ghcn-author-list__title { font-size: var(--ghcn-title-section, clamp(24px, 3vw, 32px)); font-weight: 700; line-height: 1.18; letter-spacing: -.035em; text-wrap: balance; margin: 0 0 var(--ghcn-section-gap, 20px); }
.ghcn-author-list__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr)); gap: var(--ghcn-grid-gap, 16px); }
.ghcn-author-list__grid > * { min-width: 0; }
.ghcn-author-list__empty { color: var(--muted-foreground); }
:where(.ghcn-author-list__grid) > .gh-author-card { width: 100%; margin: 0; }
